/**
 * Ordering options of parquetQuery.
 *
 * @typedef {{ orderBy?: string, descending?: boolean, nullsFirst?: boolean }} OrderOptions
 */

/**
 * Whether orderBy treats a value as missing. Flat columns decode a missing
 * value as null. Columns with nested structure decode it as undefined.
 *
 * @param {any} value
 * @returns {boolean}
 */
export function isMissing(value) {
  return value === null || value === undefined
}

/**
 * Compares two present values in ascending order. Strings compare by UTF-16
 * code unit, as the relational operators and the filter comparisons do, so the
 * order never depends on the locale of the host.
 *
 * @param {any} a
 * @param {any} b
 * @returns {number} negative when a sorts first, positive when b sorts first, 0 for a tie
 */
export function compareAscending(a, b) {
  if (a < b) return -1
  if (a > b) return 1
  return 0
}

/**
 * Throws when the ordering options contradict each other.
 * descending and nullsFirst only apply to a column order, so a flag without
 * orderBy is an error. A flag that is not a boolean is an error too.
 *
 * @param {OrderOptions} options
 */
export function checkOrderOptions({ orderBy, descending, nullsFirst }) {
  for (const [name, flag] of [['descending', descending], ['nullsFirst', nullsFirst]]) {
    if (flag !== undefined && typeof flag !== 'boolean') {
      throw new Error(`parquet ${name} must be a boolean`)
    }
  }
  if (!orderBy && (descending || nullsFirst)) {
    throw new Error('parquet descending and nullsFirst require orderBy')
  }
}

  throw new Error('parquet expected AsyncBuffer')
}
checkOrderOptions(options)

